struct Gate {std::atomic<bool>hold{true},waiting{false};static void before(void*p){auto&g=*static_cast<Gate*>(p);if(!g.hold.load())return;g.waiting=true;while(g.hold.load())std::this_thread::sleep_for(std::chrono::milliseconds(1));}};
